import {progressFor,researchXP} from './progression.js?v=20261013-repair';
export const KEY='onder-de-oppervlakte-adventure-v2';
export const fresh=()=>({version:2,routeVersion:3,briefed:[],started:false,chapter:0,room:0,beats:[],rooms:[],tools:[],completedLessons:[],knowledgePasses:[],knowledgeAnswers:{},expValues:{},exploration:{},finalAnswers:{},notes:{},trials:{},choices:{},seen:{},sorts:{},orders:{},links:{},selections:{},finalLesson:false,muted:true});
export function restore(raw,book){const s=fresh();if(raw?.version!==2)return s;const investigations=book.chapters.flatMap(c=>c.investigations),ids=new Set(investigations.flatMap(i=>i.beats.map(b=>b.id))),chapterIds=book.chapters.map(c=>c.lessonId);for(const key of ['exploration','expValues','finalAnswers','notes','trials','choices','seen','sorts','orders','links','selections','knowledgeAnswers'])if(raw[key]&&typeof raw[key]==='object'&&!Array.isArray(raw[key]))s[key]=raw[key];const list=(key,predicate)=>[...new Set((Array.isArray(raw[key])?raw[key]:[]).filter(predicate))];s.started=raw.started===true;s.muted=raw.muted!==false;s.finalLesson=raw.finalLesson===true;s.chapter=Math.max(0,Math.min(book.chapters.length-1,Math.trunc(Number(raw.chapter))||0));s.room=Math.max(0,Math.min(book.chapters[s.chapter].investigations.length-1,Math.trunc(Number(raw.room))||0));if(!raw.routeVersion&&s.chapter===0&&s.room===5)s.room=book.chapters[0].investigations.findIndex(i=>i.id==='m1-06');s.beats=list('beats',id=>ids.has(id));s.briefed=list('briefed',id=>investigations.some(i=>i.id===id));s.rooms=list('rooms',id=>investigations.some(i=>i.id===id));s.tools=list('tools',id=>['meter','map','key','camera','ledger','lens'].includes(id));s.completedLessons=list('completedLessons',id=>chapterIds.includes(id));s.knowledgePasses=list('knowledgePasses',id=>chapterIds.includes(id));if(s.finalLesson&&!s.completedLessons.includes('m1'))s.completedLessons.push('m1');return s;}
export const investigated=(s,inv)=>inv.beats.every(b=>s.beats.includes(b.id));
export const xp=researchXP;
export const level=s=>progressFor(xp(s)).current.level;
export function collect(s,beat){if(!s.beats.includes(beat.id))s.beats.push(beat.id);return s;}
export const evidenceSupports=(slot,id)=>Boolean(id&&(slot.evidenceBeatIds||[slot.evidenceBeatId]).includes(id));
export const answerSupported=(slot,answer)=>Boolean(answer&&slot.options.some(o=>o.id===answer.option&&o.correct)&&evidenceSupports(slot,answer.evidence));
export function checkFinale(s,finale,key){return finale.slots.every(slot=>answerSupported(slot,s.finalAnswers[`${key}:${slot.id}`]));}
export function finishRoom(s,inv){if(!investigated(s,inv))throw Error('Onderzoek eerst alle aanwijzingen.');if(!checkFinale(s,inv.finale,inv.id))throw Error('Onderbouw de verbanden met je bewijs.');if(!s.rooms.includes(inv.id))s.rooms.push(inv.id);return s;}
